{
  "name": "room-of-suspects",
  "version": "1.0.0",
  "private": true,
  "engines": {
    "node": ">=22.13.0"
  },
  "scripts": {
    "dev": "next dev --hostname 127.0.0.1",
    "build": "next build",
    "start": "next start --hostname 127.0.0.1",
    "typecheck": "next typegen && tsc --noEmit",
    "test": "node --import tsx --conditions=react-server --test tests/*.test.ts",
    "test:e2e": "playwright test",
    "cleanup": "node --env-file-if-exists=.env.local --import tsx --conditions=react-server scripts/cleanup.ts",
    "package": "node scripts/package.mjs"
  },
  "dependencies": {
    "next": "16.4.3",
    "react": "19.3.1",
    "react-dom": "19.3.1",
    "server-only": "0.0.1",
    "sharp": "0.35.5"
  },
  "devDependencies": {
    "typescript": "5.9.3",
    "@types/node": "^24.0.0",
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "tsx": "4.23.15",
    "@playwright/test": "1.64.1"
  }
}

{
  "compilerOptions": {
    "target": "ES2022", "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true, "skipLibCheck": true, "strict": true, "noEmit": true,
    "esModuleInterop": true, "module": "esnext", "moduleResolution": "bundler",
    "resolveJsonModule": true, "isolatedModules": true, "jsx": "react-jsx",
    "incremental": true, "plugins": [{"name":"next"}],
    "paths": {"@/*": ["./src/*"]}
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts", ".next/dev/types/**/*.ts"],
  "exclude": ["node_modules"]
}

/** The engine has no DOM, network, AI, storage, or framework dependencies. */
export const SUSPECT_IDS = ["s0", "s1", "s2"] as const;
export type SuspectId = (typeof SUSPECT_IDS)[number];
export type Locale = "ko" | "en";
export const OBJECT_KINDS = ["cup", "lamp", "electronics", "book", "plant", "toy", "other"] as const;
export type ObjectKind = (typeof OBJECT_KINDS)[number];
export const PERSONALITY_IDS = ["dry", "dramatic", "sleepy", "cheerful"] as const;
export type PersonalityId = (typeof PERSONALITY_IDS)[number];
export type StoryId = "coffee" | "sticker";

export type Claim =
  | { type: "culprit_is"; suspectId: SuspectId }
  | { type: "fact_is"; value: boolean };
export type World = { culpritId: SuspectId; fact: boolean };
export type Statement = { id: string; speakerId: SuspectId; claim: Claim };
export type Suspect = {
  id: SuspectId;
  displayName: string;
  kind: string;
  face: { x: number; y: number; scale: number; rotation: number };
  personalityId: string;
};
export type Triple<T> = [T, T, T];
export type RoleAssignment = { a: SuspectId; b: SuspectId; c: SuspectId };
export type CaseDraft = {
  schemaVersion: 1;
  templateId: "opposed-facts";
  templateVersion: 1;
  storyId: StoryId;
  storyVersion: 1;
  factId: "lamp-on-at-spill" | "bell-after-midnight";
  factSubjectId?: SuspectId;
  roleAssignment: RoleAssignment;
  factInverted: boolean;
  displayOrder: Triple<SuspectId>;
  locale: Locale;
  suspects: Triple<Suspect>;
  statements: Triple<Statement>;
};
export type PublicStatement = { id: string; speakerId: SuspectId; text: string };
export type PublicSnapshot = {
  locale: Locale;
  title: string;
  context: string;
  suspects: Suspect[];
  statements: PublicStatement[];
  characterLines: Record<SuspectId, string[]>;
  /** Optional only for immutable shares created before the interrogation expansion. */
  interrogations?: import('./interrogation').Interrogations;
  /** Public event alternatives, ordered false then true; neither is marked correct. */
  factLabels?: [string, string];
};
export type CaseResolution = {
  correct: boolean;
  accusedId: SuspectId;
  culpritId: SuspectId;
  proofSteps: string[];
  confession: string;
  fact: boolean;
};

'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import { createCase, publicSnapshot, resolveCase, type CaseDraft, type Locale, type Suspect, type SuspectId } from '@/lib/game';
import { normalizePhoto, PhotoError, rotateScene, type Scene } from '@/lib/image/normalize';
import PhotoStage, { colors } from './PhotoStage';
import GameIcon from './GameIcon';
import CrossExamination from './CrossExamination';
import HypothesisBoard from './HypothesisBoard';
import { validateCandidates } from '@/lib/ai/provider';

type Phase='start'|'casting'|'awakening'|'investigating'|'resolving'|'reveal';
type Snapshot=ReturnType<typeof publicSnapshot>;
type Verdict=ReturnType<typeof resolveCase>;
type Shared=Snapshot & {id:string;locale:Locale;scene:{url:string;width:number;height:number};suspects:Suspect[];expiresAt:string;isOwner:boolean};
const SAMPLE:Scene={dataUrl:'/sample-desk.jpg',width:1100,height:1659};
const ids:SuspectId[]=['s0','s1','s2'];
const sample=(locale:Locale):Suspect[]=>[
  {id:'s0',displayName:locale==='ko'?'컵':'Cup',kind:'cup',personalityId:'dramatic',face:{x:.661,y:.723,scale:.14,rotation:0}},
  {id:'s1',displayName:locale==='ko'?'스탠드':'Lamp',kind:'lamp',personalityId:'cheerful',face:{x:.312,y:.250,scale:.18,rotation:0}},
  {id:'s2',displayName:locale==='ko'?'키보드':'Keyboard',kind:'electronics',personalityId:'dry',face:{x:.379,y:.782,scale:.18,rotation:0}},
];
async function request<T>(url:string,body?:unknown,method?:string):Promise<T>{
  const r=await fetch(url,{method:method??(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});
  const data=await r.json();if(!r.ok)throw new Error(String(r.status));return data;
}
function chirp(index:number){
  try {const ctx=new AudioContext();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=[420,620,290][index];o.type='sine';g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.13);o.start();o.stop(ctx.currentTime+.14);o.onended=()=>void ctx.close();}catch{/* Captions always remain available. */}
}
export default function Game({shareId}:{shareId?:string}){
  const [locale,setLocale]=useState<Locale>('ko');const ko=locale==='ko';const t=(a:string,b:string)=>ko?a:b;
  const [phase,setPhase]=useState<Phase>('start');const [scene,setScene]=useState<Scene>(SAMPLE);const [suspects,setSuspects]=useState<Suspect[]>(sample('ko'));
  const [draft,setDraft]=useState<CaseDraft>();const [shared,setShared]=useState<Shared>();const [loading,setLoading]=useState(!!shareId);
  const [error,setError]=useState('');const [muted,setMuted]=useState(true);const [reduced,setReduced]=useState(false);
  const [awake,setAwake]=useState(0);const [active,setActive]=useState<SuspectId>();const [heard,setHeard]=useState<SuspectId[]>([]);const [selected,setSelected]=useState<SuspectId>();const [result,setResult]=useState<Verdict>();
  const [examined,setExamined]=useState<SuspectId[]>([]);const [spoken,setSpoken]=useState<string>();
  const [editId,setEditId]=useState<SuspectId>('s0');const [placed,setPlaced]=useState<SuspectId[]>([]);const [photoBusy,setPhotoBusy]=useState(false);
  const [analysisBusy,setAnalysisBusy]=useState(false);const [analysisAttempts,setAnalysisAttempts]=useState(0);const [analysisMessage,setAnalysisMessage]=useState('');const [aiConsent,setAiConsent]=useState(false);
  const [preview,setPreview]=useState(false);const [consent,setConsent]=useState(false);const [shareBusy,setShareBusy]=useState(false);const [created,setCreated]=useState<{id:string;url:string;expiresAt:string}>();const [copied,setCopied]=useState(false);
  const deductionRef=useRef<HTMLDivElement>(null);
  const shareOpener=useRef<HTMLButtonElement>(null);
  const wasPreview=useRef(false);
  const inputRef=useRef<HTMLInputElement>(null);const generation=useRef(0);const playId=useRef<string | undefined>(undefined);const accusationLock=useRef(false);const titleRef=useRef<HTMLHeadingElement>(null);
  const snapshot=useMemo(()=>shared??(draft?publicSnapshot(draft,locale):undefined),[shared,draft,locale]);
  const actors=shared?.suspects??snapshot?.suspects??suspects;
  useEffect(()=>{setReduced(matchMedia('(prefers-reduced-motion: reduce)').matches);},[]);
  useEffect(()=>{document.documentElement.lang=locale;setSpoken(undefined);},[locale]);
  useEffect(()=>{if(wasPreview.current&&!preview)shareOpener.current?.focus();wasPreview.current=preview;},[preview]);
  useEffect(()=>{
    if(!shareId)return;let cancelled=false;
    request<Shared>(`/api/shared-cases/${shareId}?locale=${locale}`).then(data=>{if(cancelled)return;setShared(data);setScene({dataUrl:data.scene.url,width:data.scene.width,height:data.scene.height});setLoading(false);setError('');}).catch(()=>{if(cancelled)return;setLoading(false);setError(locale==='ko'?'이 사건은 만료되었거나 삭제되었어요.':'This case has expired or was deleted.');});
    return()=>{cancelled=true;};
  },[shareId,locale]);
  useEffect(()=>{if(phase!=='start')titleRef.current?.focus();},[phase]);
  useEffect(()=>{
    if(phase!=='awakening')return;
    const timers:ReturnType<typeof setTimeout>[]=[];
    setAwake(1);setActive(actors[0].id);
    if(!muted)chirp(0);
    [1,2].forEach(i=>timers.push(setTimeout(()=>{setAwake(i+1);setActive(actors[i].id);if(!muted)chirp(i);},i===1?3200:5600)));
    timers.push(setTimeout(()=>{setAwake(3);setActive(undefined);setPhase('investigating');},8500));
    return()=>timers.forEach(clearTimeout);
    // Starting or restarting this sequence is tied only to the phase, never to the solution.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  },[phase]);
  useEffect(()=>{if(!result||!shareId||!playId.current)return;request<Verdict>(`/api/plays/${playId.current}/accuse`,{suspectId:result.accusedId,locale}).then(setResult).catch(()=>{});},[locale]);
  const reset=()=>{generation.current++;accusationLock.current=false;setDraft(undefined);setHeard([]);setExamined([]);setSpoken(undefined);setSelected(undefined);setResult(undefined);setActive(undefined);setAwake(0);setPreview(false);setCreated(undefined);setError('');setAnalysisMessage('');};
  async function begin(isSample=false){
    setError('');generation.current++;
    try{
      if(shareId){
        const stored=sessionStorage.getItem(`play:${shareId}`);
        if(stored)playId.current=stored;else{const p=await request<{playId:string}>(`/api/shared-cases/${shareId}/plays`,{});playId.current=p.playId;sessionStorage.setItem(`play:${shareId}`,p.playId);}
      }else{const list=isSample?sample(locale):suspects;if(isSample){setSuspects(list);setScene(SAMPLE);}setDraft(createCase(list));}
      setHeard([]);setExamined([]);setSpoken(undefined);setSelected(undefined);setResult(undefined);accusationLock.current=false;setPhase('awakening');
    }catch{setError(t('사건을 시작하지 못했어요. 새로고침 후 다시 시도해 주세요.','Could not start this case. Refresh and try again.'));}
  }
  function listen(id:SuspectId){if(phase!=='investigating')return;setHeard(h=>h.includes(id)?h:[...h,id]);setActive(id);setSpoken(undefined);if(!muted)chirp(ids.indexOf(id));}
  async function accuse(){
    if(!selected||!readyToAccuse||accusationLock.current)return;accusationLock.current=true;setPhase('resolving');setActive(undefined);setSpoken(undefined);
    try{const verdict=shareId?await request<Verdict>(`/api/plays/${playId.current}/accuse`,{suspectId:selected,locale}):resolveCase(draft!,selected,locale);
      await new Promise(r=>setTimeout(r,reduced?0:600));setResult(verdict);setPhase('reveal');setActive(verdict.culpritId);
    }catch{accusationLock.current=false;setPhase('investigating');setError(t('판결을 받지 못했어요. 다시 누르면 같은 지목 결과를 확인합니다.','Could not retrieve the verdict. Retry to retrieve the original result.'));}
  }
  async function upload(file?:File){
    if(!file)return;setPhotoBusy(true);setError('');
    try{const next=await normalizePhoto(file);reset();setScene(next);setSuspects(ids.map((id,i)=>({id,displayName:t(`물건 ${i+1}`,`Object ${i+1}`),kind:'other',personalityId:['dry','dramatic','sleepy'][i],face:{x:.25+i*.25,y:.5,scale:.16,rotation:0}})));setPlaced([]);setEditId('s0');setAiConsent(false);setAnalysisAttempts(0);setPhase('casting');}
    catch(e){const code=e instanceof PhotoError?e.code:'decode';setError(code==='type'?t('JPG, PNG, WebP 사진을 선택해 주세요. HEIC는 JPG로 변환하거나 샘플을 이용하세요.','Choose JPG, PNG or WebP. Convert HEIC to JPG, or try the sample.'):code==='size'?t('10MB 이하의 사진을 선택해 주세요.','Choose a photo under 10 MB.'):code==='pixels'?t('사진은 2,400만 화소 이하로 줄여 주세요.','Resize the photo to 24 megapixels or less.'):t('사진을 읽을 수 없어요. 다른 사진이나 샘플로 시작해 주세요.','This photo could not be read. Try another photo or the sample.'));}
    finally{setPhotoBusy(false);if(inputRef.current)inputRef.current.value='';}
  }
  function updateActor(id:SuspectId,patch:Partial<Suspect>){generation.current++;setSuspects(ss=>ss.map(s=>s.id===id?{...s,...patch}:s));}
  function move(id:SuspectId,x:number,y:number){const s=suspects.find(a=>a.id===id)!;updateActor(id,{face:{...s.face,x,y}});setPlaced(p=>p.includes(id)?p:[...p,id]);}
  async function analyze(){
    if(analysisAttempts>=2)return;setAnalysisAttempts(n=>n+1);
    const stamp=++generation.current;setAnalysisBusy(true);setAnalysisMessage('');
    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8500);
    try{const r=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({dataUrl:scene.dataUrl,requestId:crypto.randomUUID(),consent:true})});const data=await r.json();if(stamp!==generation.current)return;
      if(r.ok&&data.status==='ready'&&data.candidates?.length>=3){setSuspects(validateCandidates(data).slice(0,3).map((c:{displayName:string;kind:string;face:Suspect['face'];personalityId:string},i:number)=>({id:ids[i],displayName:c.displayName,kind:c.kind,personalityId:c.personalityId,face:c.face})));setPlaced([...ids]);setAnalysisMessage(t('추천 위치를 확인하고 직접 고쳐 주세요.','Check the suggested positions and adjust them.'));}
      else setAnalysisMessage(t('자동 추천을 사용할 수 없어요. 사진에서 세 물건을 직접 골라 주세요.','Suggestions are unavailable. Choose three objects directly on the photo.'));
    }catch{if(stamp===generation.current)setAnalysisMessage(t('응답이 늦거나 읽을 수 없어요. 수동 선택으로 바로 진행할 수 있습니다.','The response was late or unreadable. Continue with manual selection.'));}
    finally{clearTimeout(timer);setAnalysisBusy(false);}
  }
  async function createShare(){
    if(!draft||!consent||shareBusy)return;setShareBusy(true);setError('');
    try{let normalized=scene;if(scene.dataUrl.startsWith('/')){const blob=await(await fetch(scene.dataUrl)).blob();normalized=await normalizePhoto(new File([blob],'sample.jpg',{type:blob.type||'image/jpeg'}));}
      const data=await request<{id:string;url:string;expiresAt:string}>('/api/shared-cases',{draft,scene:normalized,consent:true});setCreated({...data,url:new URL(data.url,location.origin).href});setPreview(false);
    }catch{setError(t('링크를 만들지 못했어요. 사진과 결말은 그대로 있으니 다시 시도해 주세요.','Could not create the link. Your photo and verdict are still here; try again.'));}
    finally{setShareBusy(false);}
  }
  async function removeShare(id:string){try{await request(`/api/shared-cases/${id}`,undefined,'DELETE');setCreated(undefined);setPreview(false);if(shareId){setShared(undefined);setError(t('공유를 삭제했어요. 사진과 사건이 서버에서 제거되었습니다.','Share deleted. The photo and case were removed from the server.'));}else setError(t('공유 사진과 사건을 삭제했어요.','The shared photo and case have been deleted.'));}catch{setError(t('삭제하지 못했어요. 링크를 만든 브라우저에서 다시 시도해 주세요.','Could not delete it. Use the browser that created this link.'));}}
  const current=suspects.find(s=>s.id===editId)!;
  const line=spoken??(active?snapshot?.characterLines[active]?.[0]:undefined);
  const visibleVerdict=result&&(shareId?result:resolveCase(draft!,result.accusedId,locale));
  const allHeard=heard.length===3;
  const readyToAccuse=allHeard&&(!snapshot?.interrogations||examined.length===3);
  useEffect(()=>{if(readyToAccuse&&phase==='investigating')deductionRef.current?.focus();},[readyToAccuse,phase]);
  return <main className={reduced?'app reduced':'app'}>
    <header className="topbar">
      <a className="brand" href="/" aria-label={t('킬록 홈즈','Kirock Homes')}><img src="/art/kirolock-homes.png" alt="" width="54" height="54"/><span>{t('킬록','Kirock')}<br/><strong>{t('홈즈','Homes')}</strong></span></a>
      <div className="settings"><button onClick={()=>setMuted(v=>!v)} aria-pressed={!muted} aria-label={t(muted?'효과음 켜기':'효과음 끄기',muted?'Turn sound on':'Turn sound off')} title={t('효과음','Sound effects')}><GameIcon name={muted?'quiet':'sound'}/><span className="setting-label">{t(muted?'소리 꺼짐':'소리 켜짐',muted?'Muted':'Sound on')}</span></button><button onClick={()=>setReduced(v=>!v)} aria-pressed={reduced} aria-label={t('동작 줄이기','Reduce motion')} title={t('동작 줄이기','Reduce motion')}><GameIcon name="motion"/><span className="setting-label">{t('동작 줄이기','Less motion')}</span></button><button onClick={()=>setLocale(ko?'en':'ko')} aria-label={ko?'Switch to English':'한국어로 전환'}>{ko?'EN':'한국어'}</button></div>
    </header>
    <input className="visually-hidden" tabIndex={-1} ref={inputRef} type="file" accept="image/jpeg,image/png,image/webp" aria-label={t('사진 업로드','Upload photo')} onChange={e=>void upload(e.target.files?.[0])}/>
    {error&&<div className="notice error" role="alert">{error}{shareId&&!shared&&<a href="/">{t('새 사건 시작','Start a new case')}</a>}</div>}
    {loading?<div className="loading">{t('사건 파일을 여는 중…','Opening the case file…')}</div>:phase==='start'?<section className="landing">
      <div className="intro">
        <div className="case-stamp"><span aria-hidden="true">✦</span> {t('오늘 밤, 당신의 방에서','Tonight, in your room')}</div>
        <h1 className="game-title">{t('킬록','Kirock')}<br/>{' '}{t('홈즈','Homes')}</h1>
        <p className="game-subtitle">{t('범인은 내 방에','Room of Suspects')}</p>
        <p className="tagline">{t('깨어난 물건 셋. 거짓말은 하나.','Three suspects. One liar.')}</p>
        <p className="intro-copy">{shareId?t('친구의 사진 속에 사건이 생겼어요. 세 증언을 듣고 범인을 딱 한 번 지목하세요.','There’s a mystery in your friend’s photo. Hear three statements. Make one accusation.'):t('내 사진 한 장이 3분짜리 추리게임으로. 늘 조용하던 물건들이 오늘은 할 말이 있대요.','Turn your photo into a 3-minute mystery. Your quiet belongings have a lot to say tonight.')}</p>
        <div className="entry-actions">{shareId?<button className="primary" disabled={!shared} onClick={()=>void begin()}>{t('친구의 사건 시작하기','Play this case')}<GameIcon name="play"/></button>:<><button className="primary" onClick={()=>void begin(true)}>{t('샘플 책상에서 바로 해보기','Try the sample desk')}<GameIcon name="play"/></button><button className="secondary" disabled={photoBusy} onClick={()=>inputRef.current?.click()}>{photoBusy?t('사진을 준비하는 중…','Preparing photo…'):t('내 사진으로 사건 만들기','Make a case with my photo')}<GameIcon name="upload"/></button></>}</div>
        <div className="small-note">{t('가입 없이 · 시간제한 없이 · 자막으로 끝까지','No sign-up · No countdown · Fully captioned')}</div>
        <aside className="mascot-strip" aria-label={t('우리 집 전담 탐정 킬록 홈즈','Meet Kirock Homes, your resident detective')}><div className="detective-introduction"><span className="detective-role">{t('우리 집 전담 탐정','Your resident detective')}</span><strong>{t('킬록 홈즈','Kirock Homes')}</strong><p>“{t('이 방엔, 말 못 할 물건이 없지.','Every room has a story. Yours has suspects.')}”</p></div><img src="/art/kirolock-homes.png" alt={t('탐정 모자와 망토를 입고 작은 돋보기를 든 흰 유령 탐정','A white ghost detective in a hat and cape, holding a little magnifying glass')} width="1254" height="1254"/></aside>
      </div>
      <div className="photo-exhibit">
        <div className="desk-preview"><div className="paper-tab">{t('사건 현장','The scene')} <span aria-hidden="true">✦</span></div><PhotoStage src={scene.dataUrl} width={scene.width} height={scene.height} suspects={shared?.suspects??sample(locale)} awake={1} label={shareId?t('친구가 공유한 사건 사진','Your friend’s shared case photo'):t('컵, 스탠드, 키보드가 있는 샘플 책상','Sample desk with a cup, lamp and keyboard')}/><div className="preview-caption"><span>“{t('지금… 나 쳐다본 거야?','Did you just… look at me?')}”</span><small>{t('사진은 그대로. 수상함만 추가.','Same photo. A little more suspicious.')}</small></div></div>
        <div className="field-note"><b>{t('수사 방법','Detective’s notes')}</b><span>{t('물건 셋을 깨우고','Wake three objects')}<br/>{t('세 증언 속 거짓말을 찾아라!','Find the lie in their statements!')}</span></div>
        <img className="lens-prop" src="/art/detective-lens.png" alt="" width="140" height="140"/>
      </div>
    </section>:<>
